// State Manager - จัดการสถานะและนับรอบการทำงาน
const currentState = $input.first().json;

// ดึงค่า iteration ปัจจุบัน (ถ้าไม่มีให้เริ่มที่ 0)
const iteration = currentState.iteration || 0;

// ดึงประวัติการทำงาน (ถ้าไม่มีให้เริ่มเป็น array ว่าง)
const history = currentState.conversation_history || [];

// ตรวจสอบว่ามีคำสั่งจาก Sub-Agent หรือไม่
const lastAction = currentState.last_action || 'START';
const requiresCorrection = currentState.requires_correction || false;

// เพิ่ม iteration
const newIteration = iteration + 1;

// บันทึกลงประวัติ
history.push({
  iteration: newIteration,
  timestamp: new Date().toISOString(),
  action: lastAction,
  data: {
    orderId: currentState['Order ID'],
    amount: currentState.Amount,
    reason: currentState['Claim Reason']
  }
});

// ส่งต่อข้อมูลที่อัพเดตแล้ว
return [{
  json: {
    ...currentState,
    iteration: newIteration,
    conversation_history: history,
    case_id: `CASE-${Date.now()}`,
    status: 'PROCESSING'
  }
}];

