// Loop Back to State Manager
const input = $input.first().json;

// ตรวจสอบว่า QA ผ่านหรือไม่
const qaApproved = input.approved || false;
const requiresCorrection = input.requires_correction || false;

// อัพเดต last_action สำหรับรอบถัดไป
let nextAction = 'UNKNOWN';
if (input.intent) nextAction = 'INTENT_DONE';
else if (input.policy_passed !== undefined) nextAction = 'POLICY_DONE';
else if (input.final_amount !== undefined) nextAction = 'FINANCE_DONE';
else if (input.approved !== undefined) nextAction = 'QA_DONE';

return [{
  json: {
    ...input,
    last_action: nextAction,
    requires_correction: requiresCorrection && !qaApproved,
    // ถ้า QA ไม่ผ่าน Orchestrator จะสั่งให้วนกลับ
    loop_back: !qaApproved && requiresCorrection
  }
}];

